import 'dart:convert';
import 'dart:io';
import 'package:flutter/material.dart';
import 'package:shared_preferences/shared_preferences.dart';
import 'package:image_picker/image_picker.dart';

const navy = Color(0xFF123B78);
const blue = Color(0xFF1769D2);

void main() => runApp(const SchoolApp());

class SchoolApp extends StatelessWidget {
  const SchoolApp({super.key});
  @override
  Widget build(BuildContext context) => MaterialApp(
    title: 'School Management', debugShowCheckedModeBanner: false,
    theme: ThemeData(useMaterial3: true, colorScheme: ColorScheme.fromSeed(seedColor: blue), scaffoldBackgroundColor: const Color(0xFFF3F6FB)),
    home: const SchoolHome(),
  );
}

class SchoolHome extends StatefulWidget { const SchoolHome({super.key}); @override State<SchoolHome> createState()=>_SchoolHomeState(); }
class _SchoolHomeState extends State<SchoolHome> {
  String schoolName='New Iqra Children Academy'; String? logoPath; int selected=0;
  List<Map<String,dynamic>> students=[]; List<Map<String,dynamic>> teachers=[];
  final picker=ImagePicker();
  @override void initState(){super.initState();_load();}
  Future<void> _load() async { final p=await SharedPreferences.getInstance(); setState((){schoolName=p.getString('schoolName')??schoolName; logoPath=p.getString('logoPath'); students=(jsonDecode(p.getString('students')??'[]') as List).map((e)=>Map<String,dynamic>.from(e)).toList(); teachers=(jsonDecode(p.getString('teachers')??'[]') as List).map((e)=>Map<String,dynamic>.from(e)).toList();}); }
  Future<void> _save() async {final p=await SharedPreferences.getInstance(); await p.setString('schoolName',schoolName); if(logoPath!=null) await p.setString('logoPath',logoPath!); await p.setString('students',jsonEncode(students)); await p.setString('teachers',jsonEncode(teachers));}
  Future<void> _settings() async { final c=TextEditingController(text:schoolName); await showModalBottomSheet(context:context,isScrollControlled:true,builder:(ctx)=>Padding(padding:EdgeInsets.fromLTRB(20,20,20,20+MediaQuery.of(ctx).viewInsets.bottom),child:Column(mainAxisSize:MainAxisSize.min,crossAxisAlignment:CrossAxisAlignment.stretch,children:[const Text('School Settings',style:TextStyle(fontSize:22,fontWeight:FontWeight.bold)),const SizedBox(height:14),TextField(controller:c,decoration:const InputDecoration(labelText:'School name',border:OutlineInputBorder())),const SizedBox(height:12),OutlinedButton.icon(onPressed:()async{final x=await picker.pickImage(source:ImageSource.gallery,imageQuality:80);if(x!=null){setState(()=>logoPath=x.path);await _save();}},icon:const Icon(Icons.image),label:const Text('Choose school logo')),FilledButton(onPressed:()async{setState(()=>schoolName=c.text.trim().isEmpty?'School Management':c.text.trim());await _save();if(ctx.mounted)Navigator.pop(ctx);},child:const Text('Save'))]))); }
  Future<void> _addRecord(bool isStudent) async {final name=TextEditingController();final detail=TextEditingController();final form=GlobalKey<FormState>(); final result=await showDialog<Map<String,String>>(context:context,builder:(ctx)=>AlertDialog(title:Text(isStudent?'Add Student':'Add Teacher'),content:Form(key:form,child:Column(mainAxisSize:MainAxisSize.min,children:[TextFormField(controller:name,decoration:InputDecoration(labelText:isStudent?'Student name':'Teacher name'),validator:(v)=>v==null||v.trim().isEmpty?'Required':null),TextField(controller:detail,decoration:InputDecoration(labelText:isStudent?'Class / Roll No.':'Subject / Phone'))])),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('Cancel')),FilledButton(onPressed:(){if(form.currentState!.validate())Navigator.pop(ctx,{'name':name.text.trim(),'detail':detail.text.trim()});},child:const Text('Save'))]));if(result!=null){setState(()=> (isStudent?students:teachers).insert(0,result));await _save();}}
  Widget _brand({double size=48})=>Container(width:size,height:size,decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(14)),child:logoPath!=null&&File(logoPath!).existsSync()?ClipRRect(borderRadius:BorderRadius.circular(14),child:Image.file(File(logoPath!),fit:BoxFit.cover)):Icon(Icons.school,color:blue,size:size*.65));
  Widget _tile(String title,String subtitle,IconData icon,Color color,{VoidCallback? onTap})=>Card(child:ListTile(leading:CircleAvatar(backgroundColor:color.withOpacity(.12),child:Icon(icon,color:color)),title:Text(title,style:const TextStyle(fontWeight:FontWeight.w600)),subtitle:Text(subtitle),trailing:const Icon(Icons.chevron_right),onTap:onTap));
  Widget _dashboard()=>ListView(padding:const EdgeInsets.all(16),children:[Container(padding:const EdgeInsets.all(18),decoration:BoxDecoration(color:navy,borderRadius:BorderRadius.circular(20)),child:Row(children:[_brand(),const SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(schoolName,style:const TextStyle(color:Colors.white,fontSize:18,fontWeight:FontWeight.bold)),const Text('School Management System',style:TextStyle(color:Colors.white70))])),IconButton(onPressed:_settings,icon:const Icon(Icons.settings,color:Colors.white))])),const SizedBox(height:16),GridView.count(shrinkWrap:true,physics:const NeverScrollableScrollPhysics(),crossAxisCount:2,mainAxisSpacing:10,crossAxisSpacing:10,childAspectRatio:1.6,children:[_stat('Students','${students.length}',Icons.people,Colors.green),_stat('Teachers','${teachers.length}',Icons.person,blue),_stat('Attendance','Not recorded',Icons.fact_check,Colors.deepPurple),_stat('Fee Received','PKR 0',Icons.payments,Colors.orange)]),const SizedBox(height:12),const Text('Quick Actions',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold)),_tile('Add Student','Create student record',Icons.person_add,blue,onTap:()=>_addRecord(true)),_tile('Add Teacher','Create teacher record',Icons.co_present,Colors.teal,onTap:()=>_addRecord(false)),_tile('Exams & Marks','Marks entry and DMC generation',Icons.assignment,Colors.deepPurple,onTap:()=>_module('Exams & Marks')), _tile('ID Card / Result / Fee Card','Auto-generated printable cards',Icons.badge,Colors.orange,onTap:()=>_module('Cards & Certificates'))]);
  Widget _stat(String label,String value,IconData icon,Color color)=>Container(padding:const EdgeInsets.all(14),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(16)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Icon(icon,color:color),const Spacer(),Text(value,style:const TextStyle(fontSize:20,fontWeight:FontWeight.bold)),Text(label,style:const TextStyle(color:Colors.black54))]));
  void _module(String name)=>showDialog(context:context,builder:(ctx)=>AlertDialog(title:Text(name),content:const Text('This module is included in the project plan. Its detailed forms and PDF output will be added in the next development stage.'),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('OK'))]));
  Widget _records(bool isStudent){final list=isStudent?students:teachers;return Scaffold(backgroundColor:Colors.transparent,floatingActionButton:FloatingActionButton(onPressed:()=>_addRecord(isStudent),child:const Icon(Icons.add)),body:list.isEmpty?Center(child:Text('No ${isStudent?'students':'teachers'} added yet')):ListView.builder(padding:const EdgeInsets.all(12),itemCount:list.length,itemBuilder:(ctx,i)=>Card(child:ListTile(leading:CircleAvatar(child:Icon(isStudent?Icons.school:Icons.person)),title:Text(list[i]['name']??''),subtitle:Text(list[i]['detail']??''),trailing:IconButton(icon:const Icon(Icons.delete_outline,color:Colors.red),onPressed:()async{setState(()=>list.removeAt(i));await _save();})))));}
  @override Widget build(BuildContext context){final pages=[_dashboard(),_records(true),_records(false),const Center(child:Text('Attendance module — planned')),const Center(child:Text('Reports and PDF cards — planned'))];return Scaffold(appBar:AppBar(title:Text(selected==0?schoolName:['Dashboard','Students','Teachers','Attendance','Reports'][selected],maxLines:1,overflow:TextOverflow.ellipsis),backgroundColor:navy,foregroundColor:Colors.white),body:pages[selected],bottomNavigationBar:NavigationBar(selectedIndex:selected,onDestinationSelected:(i)=>setState(()=>selected=i),destinations:const[NavigationDestination(icon:Icon(Icons.home),label:'Home'),NavigationDestination(icon:Icon(Icons.people),label:'Students'),NavigationDestination(icon:Icon(Icons.person),label:'Teachers'),NavigationDestination(icon:Icon(Icons.fact_check),label:'Attendance'),NavigationDestination(icon:Icon(Icons.bar_chart),label:'Reports')]);}
}
